function renderNotFound() {
  return `<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>나만겜 | 영웅을 찾을 수 없습니다</title><link rel="icon" type="image/png" sizes="64x64" href="/favicon-crystal-v1.png?v=2.11.5"><link rel="stylesheet" href="/styles.css?v=2.11.5"></head><body class="hero-detail-page"><main class="wrap detail-not-found"><p class="section-kicker">404 · HERO NOT FOUND</p><h1>영웅을 찾을 수 없습니다.</h1><p>주소를 다시 확인하거나 전체 영웅도감에서 찾아보세요.</p><a class="detail-back-home" href="/">전체 영웅도감으로 이동 →</a></main></body></html>`;
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const match = url.pathname.match(/^\/hero\/([^/]+)\/?$/);

    if (url.pathname === "/newbie" || url.pathname === "/newbie/") {
      if (url.pathname === "/newbie") {
        return Response.redirect(`${SITE}/newbie/`, 301);
      }
      const body = request.method === "HEAD" ? null : renderNewbie();
      return new Response(body, {
        status: 200,
        headers: {
          "content-type": "text/html; charset=UTF-8",
          "cache-control": "public, max-age=300, s-maxage=3600",
          "x-robots-tag": "index, follow"
        }
      });
    }

    if (!match) {
      return env.ASSETS.fetch(request);
    }

    const slug = decodeURIComponent(match[1]);
    const hero = HEROES[slug];

    if (!hero) {
      return new Response(renderNotFound(), {
        status: 404,
        headers: {
          "content-type": "text/html; charset=UTF-8",
          "cache-control": "public, max-age=60"
        }
      });
    }

    const canonicalPath = `/hero/${encodeURIComponent(hero.id)}/`;
    if (url.pathname !== canonicalPath) {
      return Response.redirect(`${SITE}${canonicalPath}`, 301);
    }

    const body = request.method === "HEAD" ? null : renderHero(hero);
    return new Response(body, {
      status: 200,
      headers: {
        "content-type": "text/html; charset=UTF-8",
        "cache-control": "public, max-age=300, s-maxage=3600",
        "x-robots-tag": "index, follow"
      }
    });
  }
};
